// 插件 SDK surface 的**唯一**定义表（US-PP08）。
//
// 背景：以前 tool-host.js / panel-preload.js / block-preload.js 各手写一份 `pet` 字面量，
// 加一个 API 得改三处，漏一处就是三桥能力矩阵里的「实现漏做」（见
// docs/plugin-sdk-freeze-review.md §3 的 ③⑨⑩ 三条）。本文件把「哪个方法在哪些上下文可见、
// 参数如何归一化」收敛成数据，三份桥都由它生成。
//
// 上下文（context）三种：
//   'tool'  — tool-host.js，工具插件的 utilityProcess 子进程，调用经 parentPort RPC
//   'panel' — panel-preload.js，插件 panel BrowserWindow，调用经 ipcRenderer.invoke
//   'block' — block-preload.js，dashboard 区块 iframe（仅 plugin:// 源），同样经 invoke
// 曾经的第四条路径 buildInProcSdk（内置插件主进程内直调）已随 US-PQ03 退役——内置插件
// 现在也跑 utilityProcess，走上面的 'tool' 上下文。但它仍有一小块**不进本表**的特权面
// （host.* / auth.*，以及 pet.meetingCard / services.provide 这两个判 C 档的历史遗留）：
// 那些在 tool-host.js 的 `if (info.builtin)` 分支里单独构建。本表是**对外公共契约**，
// 把明确判 C 档不开放的特权面塞进来等于偷偷冻结新契约。见 §3 note ⑮⑯。
//
// 每条方法的上下文集合**严格照抄改动前的实际能力矩阵**，只有两处例外，均为冻结方案
// §3 点名要求 PP08 补齐的「能力已在 sdkCall 表存在、只是桥没接全」：
//   ③ ui.copyText 补到 tool（原先只有 panel/block）
//   ⑩ block 的 ai.chat 补回第二参 options（原先写作 (prompt)=>call(...) 丢参）
// 其余一律不动 —— 「顺手统一」等于偷偷冻结新契约（criteria §7 头号失败项）。
'use strict';

const ALL = ['tool', 'panel', 'block'];

// 参数归一化器：桥侧调用时对入参做的处理，改动前各桥手写在箭头函数里。
// 'raw' = 原样透传；'objDefault' = `x || {}`（原写法 `(options) => call(..., options || {})`）。
const RAW = 'raw';
const OBJ_DEFAULT = 'objDefault';

// kind:
//   'call'   — 普通转发：把 args 发给主进程 sdkCall(ns, method, args)，返回 Promise
//   'custom' — 桥内有本地状态（handler 表 / 回调表 / 代理对象），由各桥提供实现；
//              本表只负责声明它在哪些上下文出现，仍受同一份「谁有什么」裁决。
//   'const'  — 常量字段，不是函数
//
// tier（US-PP10 补，依据 docs/plugin-sdk-freeze-review.md §2 逐方法决定与 §6 执行指令）：
//   'frozen'       — A 档，进 apiVersion 契约面，同一 apiVersion 内只加不改不删
//   'experimental' — B 档，可用但签名/语义可能在任一 apiVersion 变更，不走废弃流程
//   'closed'       — C 档，本轮不作为对外契约（**运行时仍生成**，内置插件在用）
// tier 只影响对外物（金丝雀覆盖面 / 类型包 @experimental / 脚手架样板），**不影响 buildSdk
// 与 generate-preload-surface 的生成结果**——运行时行为等价是 US-PP08 的硬要求。
const FROZEN = 'frozen';
const EXPERIMENTAL = 'experimental';
const CLOSED = 'closed';

const SURFACE = [
  // ---- storage：四路径一致。全 A 档（§2.1）----
  { ns: 'storage', method: 'get', contexts: ALL, argSpec: [RAW, RAW], tier: FROZEN },
  { ns: 'storage', method: 'set', contexts: ALL, argSpec: [RAW, RAW], tier: FROZEN },
  { ns: 'storage', method: 'delete', contexts: ALL, argSpec: [RAW], tier: FROZEN },
  { ns: 'storage', method: 'all', contexts: ALL, argSpec: [], tier: FROZEN },

  // ---- secrets：**有意**只给能跑代码的上下文（§3 note①）。渲染层读密钥 = XSS 等于泄漏。全 A 档（§2.2）
  { ns: 'secrets', method: 'get', contexts: ['tool'], argSpec: [RAW], tier: FROZEN },
  { ns: 'secrets', method: 'set', contexts: ['tool'], argSpec: [RAW, RAW], tier: FROZEN },
  { ns: 'secrets', method: 'delete', contexts: ['tool'], argSpec: [RAW], tier: FROZEN },

  // ---- pet：三桥一致（pet.meetingCard 不在任何桥上，§3 note②，此处也不加）。三个都 A 档（§2.3）
  { ns: 'pet', method: 'bubble', contexts: ALL, argSpec: [RAW, RAW], tier: FROZEN },
  { ns: 'pet', method: 'playAnim', contexts: ALL, argSpec: [RAW], tier: FROZEN },
  { ns: 'pet', method: 'speak', contexts: ALL, argSpec: [RAW], tier: FROZEN },

  // ---- ui：4 A / 1 B / 1 C（§2.4）----
  { ns: 'ui', method: 'dialog', contexts: ALL, argSpec: [RAW], tier: FROZEN },
  // B：13 个可选字段的专用卡，与 §3.2 声明式聊天卡片 API 高度重叠，冻死等于上枷锁
  { ns: 'ui', method: 'taskCheck', contexts: ALL, argSpec: [RAW], tier: EXPERIMENTAL },
  // ③ 补齐：sdkCall 表本就有 copyText 且无上下文限制，原先只有两个渲染层桥暴露。
  { ns: 'ui', method: 'copyText', contexts: ALL, argSpec: [RAW], tier: FROZEN },
  { ns: 'ui', method: 'openPanel', contexts: ['tool'], argSpec: [], tier: FROZEN },      // §3 note④
  { ns: 'ui', method: 'closePanel', contexts: ['tool', 'panel'], argSpec: [], tier: FROZEN }, // §3 note⑤
  // B：panel 置顶/失焦关闭策略可供 tool 预设，也可由 panel 自身切换；未调用时保持历史 alwaysOnTop 行为
  { ns: 'ui', method: 'setPanelPinned', contexts: ['tool', 'panel'], argSpec: [RAW], tier: EXPERIMENTAL },
  // C：§3.2 已拍板主题升级为语义 Token 覆写，裸 CSS 注入不进对外契约（运行时保留）
  { ns: 'ui', method: 'injectStyle', contexts: ['tool'], argSpec: [RAW], tier: CLOSED }, // §3 note⑥

  // ---- events：on 要维护桥内回调表，故 custom；emit 是普通转发。全 A 档（§2.5）----
  { ns: 'events', method: 'on', contexts: ALL, kind: 'custom', tier: FROZEN },
  { ns: 'events', method: 'emit', contexts: ALL, argSpec: [RAW, RAW], tier: FROZEN },

  // ---- scheduler：**有意**仅 tool（§3 note⑦），回调要存在桥内 → custom。全 A 档（§2.6）----
  { ns: 'scheduler', method: 'every', contexts: ['tool'], kind: 'custom', tier: FROZEN },
  { ns: 'scheduler', method: 'daily', contexts: ['tool'], kind: 'custom', tier: FROZEN },
  { ns: 'scheduler', method: 'cancel', contexts: ['tool'], kind: 'custom', tier: FROZEN },

  // ---- net：**有意**仅 tool（§3 note⑧），渲染层用原生 fetch 受 CSP 约束。A 档，per-hostname 权限保留（§2.7）
  { ns: 'net', method: 'fetch', contexts: ['tool'], argSpec: [RAW, RAW], tier: FROZEN },

  // ---- services：get 要先取方法列表再造代理 → custom，A 档（§2.8）。
  //      provide 三桥都没有（§3 note⑨，本轮不补，判 C），故不在表中。
  { ns: 'services', method: 'get', contexts: ALL, kind: 'custom', tier: FROZEN },

  { ns: 'settings', method: 'get', contexts: ALL, argSpec: [], tier: FROZEN },   // §2.9

  // ⑩ 补齐：block 原写法丢了 options，改为三桥同签名。B 档：options 是活的（§2.10）
  { ns: 'ai', method: 'chat', contexts: ALL, argSpec: [RAW, OBJ_DEFAULT], tier: EXPERIMENTAL },

  // ---- files：**有意** block 无（§3 note⑪），区块小卡片不该唤起系统文件选择器。
  //      整组 B 档（§2.11，criteria 点名的高后悔风险区）----
  { ns: 'files', method: 'pick', contexts: ['tool', 'panel'], argSpec: [OBJ_DEFAULT], tier: EXPERIMENTAL },
  { ns: 'files', method: 'stat', contexts: ['tool', 'panel'], argSpec: [RAW], tier: EXPERIMENTAL },
  { ns: 'files', method: 'open', contexts: ['tool', 'panel'], argSpec: [RAW], tier: EXPERIMENTAL },
  { ns: 'files', method: 'list', contexts: ['tool', 'panel'], argSpec: [], tier: EXPERIMENTAL },
  { ns: 'files', method: 'revoke', contexts: ['tool', 'panel'], argSpec: [RAW], tier: EXPERIMENTAL },
  { ns: 'files', method: 'pin', contexts: ['tool', 'panel'], argSpec: [RAW, OBJ_DEFAULT], tier: EXPERIMENTAL },
