 * 生成某个上下文的 `pet` 对象。
 * @param {'tool'|'panel'|'block'} context 上下文名
 * @param {(ns:string, method:string, args:any[]) => any} invoke 该桥的转发通道
 *        （tool → parentPort RPC；panel/block → ipcRenderer.invoke）
 * @param {Record<string, Record<string, Function>>} custom kind:'custom' 方法的桥内实现，
 *        形如 { events: { on(...) {} }, tools: { register(...) {} } }。
 *        本表声明该上下文有的 custom 方法若未提供实现，直接抛错——宁可启动即炸，
 *        也不要静默少一个 API 让插件在运行期拿到 undefined。
 */
function buildSdk(context, invoke, custom) {
  const impls = custom || {};
  const pet = {};
  for (const entry of SURFACE) {
    if (!entry.contexts.includes(context)) continue;
    if (entry.kind === 'const') {
      pet[entry.method] = entry.value;         // ns 为 null 的顶层常量字段
      continue;
    }
    const bucket = pet[entry.ns] || (pet[entry.ns] = {});
    if (entry.kind === 'custom') {
      const fn = impls[entry.ns] && impls[entry.ns][entry.method];
      if (typeof fn !== 'function') {
        throw new Error(`[sdk-surface] ${context} 上下文缺少 ${entry.ns}.${entry.method} 的实现`);
      }
      bucket[entry.method] = fn;
      continue;
    }
    const { ns, method, argSpec } = entry;
    bucket[method] = (...args) => invoke(ns, method, normalizeArgs(argSpec, args));
  }
  return pet;
}

/** 某上下文可见的 "ns.method" 列表（契约测试 / 能力矩阵核对用）。 */
function listSurface(context) {
  return SURFACE
    .filter((e) => e.contexts.includes(context))
    .map((e) => (e.ns ? `${e.ns}.${e.method}` : e.method));
}

/**
 * A 档（frozen）方法在某上下文的条目列表。
 * 金丝雀契约测试（US-PP10）与类型包（US-PP11）的覆盖依据——**只有 frozen 才是承诺**，
 * experimental/closed 不进契约测试（把 experimental 写进契约测试等于用测试把它冻上，
