 * @param {'tool'|'panel'|'block'} [context] 不传则返回全部上下文的 frozen 条目
 */
function frozenSurface(context) {
  return SURFACE.filter((e) => e.tier === FROZEN && (!context || e.contexts.includes(context)));
}

module.exports = {
  SURFACE, CONTEXTS: ALL, buildSdk, listSurface, frozenSurface,
  TIERS: { FROZEN, EXPERIMENTAL, CLOSED }
};

