test('空态：三要素 + 未接入显蓝色主按钮，Codex 是灰字非按钮', () => {
  const p = mountPanel();
  p.push('agent-status:snapshot', { rows: [], summary: { running: 0, waiting: 0, total: 0, unknown: 0 } });

  assert.strictEqual(p.$('#empty').hidden, false, '无会话时应显示空态');
