  for (const d of tmpDirs) fs.rmSync(d, { recursive: true, force: true });

  if (failures.length) {
    console.log(`\ntool-lifecycle-test: ${passed} passed, ${failures.length} FAILED`);
    process.exit(1);
  }
  console.log(`\ntool-lifecycle-test: ${passed} passed`);
})();

