test('5 行快照：行数 / waiting 置顶且带描边 class / 各行状态 class / 汇总胶囊', () => {
  // 乱序喂入，排序由 aggregate 定（panel 只按数组顺序渲染）
  const snap = snapshotOf([
    rec({ sessionId: 'r-old', state: 'running', project: 'blog', ts: T0 - 30 * 1000 }),
