    rec({ sessionId: 'r-new', state: 'running', project: 'desktop_pet', ts: T0 - 5 * 1000 })
  ], { isPidAlive: (pid) => pid !== 999999 });

  // 快照里必须真有这五种态，否则下面的断言是空转
  assert.deepStrictEqual(
    snap.rows.map((r) => r.state).sort(),
    ['error', 'idle', 'running', 'running', 'waiting']
  );

  const p = mountPanel();
